def knapsack(items, capacity):
    dp = [0] * (capacity + 1)

    for weight, value in items:
        if weight == 0:
            for w in range(capacity, -1, -1):
                dp[w] = max(dp[w], dp[w] + value)
        else:
            for w in range(capacity, weight - 1, -1):
                candidate = dp[w - weight] + value
                if candidate > dp[w]:
                    dp[w] = candidate

    return dp[capacity]
